//! 🧪️ Native document projection preserves the portable four-field shape and every original immutable authority.
use super::*;
use crate::state::tests::{receive,source,drain,grant,observe};
use semio_framework_value_snapshot_projection::snapshot_projection::{SnapshotProjection,SnapshotProjectionCursor};
use semio_framework_value::retained_clone::{RetainedCloneProgress,RetainedCloneGrant};
fn fixture()->(serde_json::Value,serde_json::Value){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let model:serde_json::Value=serde_json::from_str(include_str!("../../../../🧪️tests/🧫️fixtures/📸️snapshot/🧳️state/🔣️.json")).unwrap();let mut document=law["document"].clone();document["model"]=model["model"].clone();(law,document)}
#[test]
fn original_energy_document_projection_retains_authorities_and_exact_physical_receipts(){
 let(law,document)=fixture();let original=source(receive::<EnergyModelSnapshot>(&document));let schema=original.borrow().get().schema.identity();let model=original.borrow().get().model.geometry.identity();let reference=original.borrow().get().referenced_model.identity();let weather=original.borrow().get().weather_link.identity();
 let d=EnergyModelSnapshot::projection_birth_demand();let g=grant(d);let((mut cursor,p),heap)=observe(||EnergyModelSnapshot::begin_projection(g).unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));
 for index in 0..100000{if cursor.ready(){break;}let d=cursor.demands(original.borrow(),4096).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let(step,heap)=observe(||cursor.advance(original.borrow(),4096,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(cursor.demands(original.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||cursor.advance(original.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999,"native Energy document projection stalled");}
 let g=grant(cursor.take_demand().unwrap());let((output,p),heap)=observe(||cursor.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(output.schema.identity()==schema,law["projection"]["sameSchemaAuthority"].as_bool().unwrap());assert_eq!(output.model.geometry.identity()==model,law["projection"]["sameModelBranchAuthority"].as_bool().unwrap());assert_eq!(output.referenced_model.identity()==reference&&output.weather_link.identity()==weather,law["projection"]["sameLinkAuthorities"].as_bool().unwrap());crate::state::tests::assert_portable_value(semio_framework_value::ToValue::to_value(output.as_ref()),&document);
 cursor.begin_close();for index in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999,"native Energy document projection close stalled");}assert!(cursor.terminal_is_empty());assert!(<EnergyModelSnapshot as semio_framework_schema_composition::ArtifactCompositionFields>::child_slots().is_empty());let links=<EnergyModelSnapshot as semio_framework_schema_composition::ArtifactCompositionFields>::link_slots();assert_eq!(links.len(),2);assert_eq!(links[0].roles,&["model"]);assert_eq!(links[1].roles,&["weather"]);drain(output);drain(original);
}
#[test]
fn original_energy_document_projection_cancels_each_portable_prefix(){let(law,document)=fixture();for cut in law["cancelAt"].as_array().unwrap(){let original=source(receive::<EnergyModelSnapshot>(&document));let d=EnergyModelSnapshot::projection_birth_demand();let(mut cursor,_)=EnergyModelSnapshot::begin_projection(grant(d)).unwrap();for _ in 0..cut.as_u64().unwrap(){if cursor.ready(){break;}let g=grant(cursor.demands(original.borrow(),4096).unwrap());let(step,heap)=observe(||cursor.advance(original.borrow(),4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}cursor.begin_close();for index in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(step,heap)=observe(||cursor.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(index<99999,"native Energy cancellation stalled");}assert!(cursor.terminal_is_empty());drain(original);}}

#[test]
fn native_document_link_binding_and_detachment_preserve_original_model_and_inverse_slot_authority(){
 use crate::state::tests::{central_fragment,project_record,projected_source};
 use protocol::{RetainedRowPatchFields,RetainedPatchSource};
 let(law,document)=fixture();let original=source(receive::<EnergyModelSnapshot>(&document));let weather=receive::<semio_framework_value::shared_issuance::SealedShared<Option<store::ArtifactLink>>>(&law["weather"]);let authored=source(crate::native_diff::EnergyModelDiff{weather_link:Some(weather),..Default::default()});let mut post=project_record(original.borrow());assert!(central_fragment(&authored,original.borrow(),&mut post));assert_eq!(post.model.geometry.identity(),original.borrow().get().model.geometry.identity());assert_eq!(post.schema.identity(),original.borrow().get().schema.identity());assert_eq!(post.referenced_model.identity(),original.borrow().get().referenced_model.identity());assert_eq!(post.weather_link.get().as_ref().unwrap().target.artifact_id,law["weather"]["target"]["artifactId"].as_str().unwrap());assert!(original.borrow().get().weather_link.get().is_none());
 let mut inverse=crate::native_diff::link_fields::Fields::new(RetainedPatchSource::Inverse);for _ in 0..100000{let g=grant(inverse.demand(authored.borrow(),original.borrow(),4096).unwrap());let(s,h)=observe(||inverse.advance(authored.borrow(),original.borrow(),4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if matches!(s,semio_framework_value::RetainedCloneStep::Complete(_)){break;}}let g=grant(semio_framework_value::RetirementDemand{copy_bytes:2*std::mem::size_of::<crate::native_diff::EnergyModelDiff>(),depth:1,..Default::default()});let(undo,p)=inverse.take(g).unwrap();assert!(p.fits(g));let undo=undo.unwrap();assert_eq!(undo.weather_link.as_ref().unwrap().identity(),original.borrow().get().weather_link.identity());inverse.begin_close();for _ in 0..100000{if inverse.terminal_is_empty(){break;}let g=grant(inverse.close_demand(4096).unwrap());let(s,h)=observe(||inverse.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(inverse.terminal_is_empty());let changed=projected_source(post);let mut restored=project_record(changed.borrow());let undo=source(undo);assert!(central_fragment(&undo,changed.borrow(),&mut restored));assert_eq!(restored.weather_link.identity(),original.borrow().get().weather_link.identity());crate::state::tests::assert_portable_value(semio_framework_value::ToValue::to_value(restored.as_ref()),&document);drain(restored);drain(undo);drain(changed);drain(authored);drain(original);
}
